package com.sentinelguard.keystore

import androidx.room.*

// ─────────────────────────────────────────────────────────────────────────────
// Entity
// ─────────────────────────────────────────────────────────────────────────────

/**
 * [SignedVerdictEntity] — a hardware-signed threat verdict persisted to Room.
 *
 * Every [com.sentinelguard.vpn.ThreatEvent] that passes through the
 * [com.sentinelguard.vpn.ConnectionAnalyser] is signed by [SentinelKeyManager]
 * and stored here as an auditable, tamper-evident log entry.
 *
 * @param id            Auto-generated primary key.
 * @param threatType    Machine-readable threat label (e.g. "DNS_THREAT", "SMS_SCAM").
 * @param severity      "LOW" | "MEDIUM" | "HIGH".
 * @param confidence    Classifier confidence in [0.0, 1.0]; 0.0 for network threats
 *                      that don't carry a confidence score.
 * @param timestamp     Epoch-millisecond of the original [ThreatEvent].
 * @param signatureHex  DER-encoded ECDSA signature over the JSON-serialised
 *                      [VerdictPayload], represented as a lowercase hex string.
 * @param publicKeyHex  X.509 SubjectPublicKeyInfo encoding of the signing key,
 *                      represented as a lowercase hex string. Stored alongside
 *                      the signature so off-device verifiers can validate without
 *                      accessing the device Keystore.
 */
@Entity(tableName = "signed_verdicts")
data class SignedVerdictEntity(
    @PrimaryKey(autoGenerate = true)
    val id:           Long   = 0,
    val threatType:   String,
    val severity:     String,
    val confidence:   Float,
    val timestamp:    Long,
    val signatureHex: String,
    val publicKeyHex: String,
    /** Raw content that triggered the verdict (domain, URL, SMS text snippet). */
    val content:      String = "",
    /** ML classifier label (e.g. "Smishing", "Malware"). Empty if classifier unavailable. */
    val mlLabel:      String = "",
    /** Plain-English explanation generated by LlamaExplainer on user tap. Empty until requested. */
    val explanation:  String = ""
)

// ─────────────────────────────────────────────────────────────────────────────
// DAO
// ─────────────────────────────────────────────────────────────────────────────

@Dao
interface SignedVerdictDao {

    /**
     * Persist a signed verdict. Returns the auto-generated row ID.
     * Called from [com.sentinelguard.keystore.VerdictLogger] on every threat event.
     */
    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun insert(entity: SignedVerdictEntity): Long

    /**
     * Return all stored verdicts ordered newest-first.
     * Used by the audit / export feature (future UI).
     */
    @Query("SELECT * FROM signed_verdicts ORDER BY timestamp DESC")
    suspend fun getAll(): List<SignedVerdictEntity>

    /** Return verdicts for a specific threat type, newest-first. */
    @Query("SELECT * FROM signed_verdicts WHERE threatType = :type ORDER BY timestamp DESC")
    suspend fun getByType(type: String): List<SignedVerdictEntity>

    /** Return the total number of stored verdicts. */
    @Query("SELECT COUNT(*) FROM signed_verdicts")
    suspend fun count(): Long

    /**
     * Delete verdicts older than [beforeTimestamp].
     * Called periodically to prevent unbounded DB growth.
     */
    @Query("DELETE FROM signed_verdicts WHERE timestamp < :beforeTimestamp")
    suspend fun deleteBefore(beforeTimestamp: Long)

    /**
     * Persist the Llama-generated [text] explanation for a specific verdict row.
     * Called from [com.sentinelguard.ui.MainViewModel.saveExplanation] after the
     * ExplanationBottomSheet streaming session completes.
     */
    @Query("UPDATE signed_verdicts SET explanation = :text WHERE id = :id")
    suspend fun updateExplanation(id: Long, text: String)
}
